// Applica le modifiche: rotta POST /api/viaggi/proponi (bozza viaggio da testo).
// Uso: salva nella cartella radice del progetto e lancia:  node applica-modifiche.js
import { writeFileSync, mkdirSync } from 'fs'
import { dirname } from 'path'

const files = {
  "functions/api/[[path]].js": '',
}

for (const [percorso, b64] of Object.entries(files)) {
  mkdirSync(dirname(percorso), { recursive: true })
  writeFileSync(percorso, Buffer.from(b64, 'base64'))
  console.log('scritto:', percorso)
}

console.log('\nFatto. Controlla i file, poi git add / commit / push.')